// Noise dissolve — warm gradient burns away with a glowing edge over the layer's progress.
uniform vec3  uColorTop;   // @param #FFB347
uniform vec3  uColorBot;   // @param #E2412A
uniform vec3  uEdgeColor;  // @param #FFC45A
uniform vec3  uCharColor;  // @param #2A0E05
uniform float uScale;      // @param 4.0 0.5 16
uniform float uEdge;       // @param 0.08 0.005 0.3
uniform float uGlow;       // @param 2.5 0 8
uniform float uDrift;      // @param 0.08 0 1

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);

  // Dissolve noise, remapped to roughly 0..1
  float n = fbm(p * uScale + vec2(iTime * uDrift, -iTime * uDrift * 0.7));
  n = 0.75 * n + 0.25 * fbm(p * uScale * 3.1 + 7.3);
  n = clamp((n - 0.2) / 0.6, 0.0, 1.0);

  // Threshold sweeps so progress 0 = intact, progress 1 = fully gone
  float e = max(uEdge, 1e-3);
  float thr = mix(-e - 0.01, 1.01, clamp(iProgress, 0.0, 1.0));
  if (n < thr) discard;

  // Edge factor: 1 at the burn front, 0 once uEdge away from it
  float edge = 1.0 - smoothstep(0.0, e, n - thr);

  // Warm gradient with a gentle sheen
  float g = clamp(uv.y + 0.08 * sin(uv.x * 6.2831 + iTime * 0.5), 0.0, 1.0);
  vec3 col = mix(uColorBot, uColorTop, g);

  // Char band then glowing rim
  col = mix(col, uCharColor, smoothstep(0.0, 0.6, edge));
  col += uEdgeColor * uGlow * pow(edge, 3.0);

  fragColor = vec4(col, 1.0);
}
